const REGEX_ROWS = [
    ['*молоко*', 'МОЛОКО 3,2% 930 мл', 'Любой текст до и после слова «молоко»'],
    ['сыр ?00г', 'сыр 200г', 'Один любой символ вместо знака ?'],
    ['^ооо', 'ООО Ромашка', 'Последовательность «ооо» только в начале'],
    ['магазин$', 'Продуктовый магазин', 'Последовательность «магазин» только в конце'],
    ['перекр[её]сток', 'Перекрёсток', 'Буква «е» или «ё» в указанной позиции'],
    ['кофе|капучино', 'Капучино 300 мл', 'Один из двух вариантов'],
    ['\\s+', 'Сыр   200 г', 'Один или несколько пробельных символов'],
    ['.*', 'Любое название', 'Любое количество любых символов'],
] as const

function RegexGuide() {
    return (
        <>
            <GuideSection title="Сначала попробуйте обычное правило">
                <Text>Обычное правило выполняет поиск подстроки без учёта регистра. Поля правила задают исходный фрагмент, итоговое название, область применения — товар или магазин — и приоритет.</Text>
                <Text><strong>Полный пример.</strong> Область применения — «Магазины», исходный фрагмент — <Code>перекресток</Code>, итоговое название — «Перекрёсток», приоритет — 100, расширенный шаблон выключен. Правило сопоставит названия «АО ТД Перекресток» и «ПЕРЕКРЕСТОК № 42», потому что оба содержат исходный фрагмент без учёта регистра. Название «Пятёрочка» не соответствует правилу и останется без изменений.</Text>
            </GuideSection>
            <GuideSection title="Что такое regex">
                <Text>Регулярное выражение, или regex, — формальный шаблон для сопоставления текста. Оно применяется без учёта регистра и требуется, когда условие нельзя выразить одной подстрокой. На странице <Link component={RouterLink} to="/rules" color="primary" underline="hover" fontWeight={700}>«Правила»</Link> включите «Расширенный шаблон». Конструктор позволяет добавить строку, альтернативу «Или», цифры, пробелы, начало или конец названия.</Text>
                <Stack spacing={0} divider={<Divider flexItem />} sx={{ border: '1px solid', borderColor: 'divider', borderRadius: '8px', overflow: 'hidden' }}>
                    <Box sx={{ display: { xs: 'none', sm: 'grid' }, gridTemplateColumns: '130px minmax(140px, 0.8fr) 1.2fr', gap: 1, p: 1.25, bgcolor: 'action.hover' }}>
                        <Typography variant="caption" sx={{ fontWeight: 700 }}>Шаблон</Typography>
                        <Typography variant="caption" sx={{ fontWeight: 700 }}>Пример совпадения</Typography>
                        <Typography variant="caption" sx={{ fontWeight: 700 }}>Значение</Typography>
                    </Box>
                    {REGEX_ROWS.map(([pattern, source, meaning]) => (
                        <Box key={pattern} sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', sm: '130px minmax(140px, 0.8fr) 1.2fr' }, gap: 1, p: 1.25, bgcolor: 'background.paper' }}>
                            <Box component="code" sx={{ fontFamily: 'monospace', color: 'primary.main', fontWeight: 700 }}>{pattern}</Box>
                            <Typography variant="body2">{source}</Typography>
                            <Typography variant="body2" color="text.secondary">{meaning}</Typography>
                        </Box>
                    ))}
                </Stack>
            </GuideSection>
            <GuideSection title="Полный пример расширенного правила">
                <Text>Область применения — «Товары», шаблон — <Code>^молоко.*930\s?мл$</Code>, итоговое название — «Молоко, 930 мл», приоритет — 100, расширенный шаблон включён. Шаблон соответствует названиям «Молоко 3,2% 930 мл» и «МОЛОКО 2.5% 930мл»: <Code>^</Code> фиксирует начало, <Code>.*</Code> допускает любой текст в середине, <Code>\s?</Code> допускает отсутствие или наличие одного пробела, а <Code>$</Code> фиксирует конец. Название «Молоко 1 л» не соответствует условию. После применения у совпавших операций нормализованное название станет «Молоко, 930 мл», а исходное название сохранится.</Text>
            </GuideSection>
            <GuideSection title="Приоритет правил">
                <Text>Если подходят несколько правил, побеждает правило с большим приоритетом. При одинаковом приоритете применяется более длинный шаблон. Узкие правила ставьте выше общих.</Text>
            </GuideSection>
            <Alert severity="info" sx={{ borderRadius: '8px' }}>
                В расширенном шаблоне <Code>*</Code> преобразуется сервером в regex <Code>.*</Code>, а <Code>?</Code> — в <Code>.</Code>. Экранированные <Code>\*</Code> и <Code>\?</Code>, а также символы внутри квадратных скобок, остаются буквальными. Чтобы искать точку буквально, добавьте обычную строку через конструктор или напишите <Code>\.</Code>. Начинайте с узкого шаблона: один <Code>*</Code> совпадёт почти со всем.
            </Alert>
            <GuideSection title="Как применяются изменения">
                <Text>После сохранения правило применяется к подходящим существующим записям. Кнопка «Применить все алиасы» повторно строит нормализованные названия из сохранённых исходных значений. При изменении или удалении правила значения также пересчитываются. Перед сохранением проверьте шаблон на нескольких исходных названиях: слишком общее условие может временно объединить разные товары или магазины и повлиять на аналитику и автотегирование.</Text>
            </GuideSection>
        </>
    )
}

function DataGuide() {
    return (
        <>
            <GuideSection title="Экспорт">
                <Text>Экспорт создаёт файл XLSX со всеми операциями пользователя. Перед выгрузкой выберите структуру: один общий лист «Транзакции» или отдельный лист для каждого календарного месяца. Оба варианта содержат одинаковые колонки: «Дата», «Категория», «Магазин», «Описание», «Количество», «Единица», «Цена», «Комментарий», «Доход» и «Расход».</Text>
                <Text>Экспортированный файл соответствует формату импорта и может использоваться как переносимая копия данных. Экспорт не удаляет и не изменяет записи в аккаунте.</Text>
            </GuideSection>
            <GuideSection title="Требования к файлу импорта">
                <Bullet>Поддерживаются XLSX и CSV. Файл CSV может использовать кодировку UTF-8 или Windows-1251 и разделитель «точка с запятой» либо «запятая».</Bullet>
                <Bullet>Строка заголовков должна находиться среди первых пяти строк каждого листа. Порядок колонок не имеет значения; неизвестные колонки игнорируются.</Bullet>
                <Bullet>Обязательны колонки «Дата» и «Описание», а также хотя бы одна из колонок «Доход» или «Расход». Остальные колонки являются необязательными.</Bullet>
                <Bullet>Дата может быть датой Excel либо текстом в формате <Code>ДД.ММ.ГГГГ</Code>, <Code>ДД.ММ.ГГ</Code> или <Code>ГГГГ-ММ-ДД</Code>.</Bullet>
                <Bullet>В одной строке должна быть указана сумма дохода или расхода. Отрицательные суммы не принимаются; одновременное положительное значение в обеих колонках считается ошибкой.</Bullet>
            </GuideSection>
            <GuideSection title="Полный пример строки">
                <Text>Заголовки: <Code>Дата | Категория | Магазин | Описание | Количество | Единица | Цена | Комментарий | Доход | Расход</Code>.</Text>
                <Text>Гипотетическая строка расхода: <Code>15.03.2026 | Продукты | Магазин у дома | Молоко 3,2 %, 930 мл | 2 | шт. | 89,90 | Покупка по списку | [пусто] | 179,80</Code>. После импорта будет создана расходная операция на 179,80 с указанными описанием, магазином и категорией. Пустая колонка «Доход» означает, что строка не является доходной операцией.</Text>
            </GuideSection>
            <GuideSection title="Предпросмотр и сохранение">
                <Text>После выбора файла AutoEco сначала формирует предпросмотр и не записывает операции автоматически. В нём строки разделяются на готовые, возможные дубликаты и строки с ошибками. Дубликаты по умолчанию не выбраны, но их можно включить вручную, если повторная запись нужна намеренно. Строки с ошибками необходимо исключить или исправить в исходном файле.</Text>
                <Text>При подтверждении сохраняются только выбранные допустимые строки. Если в колонке «Категория» указано отсутствующее название, соответствующий тег создаётся автоматически с оформлением по умолчанию. После завершения сравните итоговые счётчики с предпросмотром и сохраните исходный файл до окончания проверки.</Text>
            </GuideSection>
        </>
    )
}

function AutoTaggingGuide() {
    return (
        <>
            <Alert severity="info" sx={{ borderRadius: '8px' }}>
                Автотегирование — экспериментальная персональная функция. Она назначает тег новой операции только после проверки качества на данных того же пользователя. Если надёжный ответ получить нельзя, операция сохраняется без тега.
            </Alert>
            <GuideSection title="Основные понятия">
                <Bullet><strong>Модель</strong> — алгоритм, который находит закономерности между признаками операции и ранее назначенными тегами.</Bullet>
                <Bullet><strong>Ручной пример</strong> — операция, тег которой выбрал или сохранил пользователь. Только такие операции участвуют в следующем обучении.</Bullet>
                <Bullet><strong>Предсказание</strong> — тег, выбранный моделью для новой операции.</Bullet>
                <Bullet><strong>Уверенность</strong> — внутренний числовой показатель модели. Это не гарантированная вероятность правильного ответа; показатель используется только для сравнения с проверенным порогом.</Bullet>
                <Bullet><strong>Проверочная часть</strong> — последние операции, временно исключённые из обучения, чтобы оценить работу модели на более новых данных.</Bullet>
            </GuideSection>
            <GuideSection title="Какие данные используются">
                <Text>Функция включается в <Link component={RouterLink} to="/profile" color="primary" underline="hover" fontWeight={700}>профиле</Link>. Для одного цикла берётся не более 10 000 последних операций с ручными тегами. Операции с автоматически назначенным тегом не используются как новые примеры до тех пор, пока пользователь не сохранит или не исправит тег вручную. Это предотвращает обучение модели на собственных неподтверждённых ответах.</Text>
                <Text>Для каждой операции формируется набор признаков: исходное название, нормализованное название после применения алиасов, тип операции — доход или расход — и диапазон суммы по порядку величины. Название магазина обрабатывается отдельно и используется только как дополнительный сигнал.</Text>
            </GuideSection>
            <GuideSection title="Структура модели">
                <Bullet><strong>История точных совпадений.</strong> Для каждого нормализованного названия подсчитываются ручные теги. Совпадение считается устойчивым, если название встречалось не менее трёх раз и один тег использовался как минимум в 90 % этих случаев.</Bullet>
                <Bullet><strong>Текстовый классификатор.</strong> Название разбивается на последовательности длиной от трёх до пяти символов. Вектор признаков фиксированного размера строится методом хеширования, после чего логистическая регрессия оценивает соответствие каждому тегу. Балансировка классов уменьшает влияние категорий с особенно большим числом примеров.</Bullet>
                <Bullet><strong>Резервное правило по магазину.</strong> Оно создаётся только для магазинов, которые встречались не менее 20 раз и были связаны с одним тегом как минимум в 95 % случаев. Правило используется, если текстовый классификатор не дал ответа с уверенностью 55 %, либо если оба метода выбрали один тег.</Bullet>
                <Bullet><strong>Фильтр качества.</strong> Итоговое предсказание возвращается только тогда, когда его уверенность достигает отдельного порога, рассчитанного для выбранного тега.</Bullet>
            </GuideSection>
            <GuideSection title="Почему выбрана такая архитектура">
                <Text>Модель строится отдельно для каждого пользователя, поэтому должна работать на сравнительно небольших наборах данных и быстро обновляться на обычном процессоре. Символьные признаки устойчивы к сокращениям, окончаниям слов и различиям в оформлении кассовых наименований. Хеширование не требует хранить отдельный словарь и ограничивает размер признакового пространства. Логистическая регрессия подходит для многоклассовой классификации и предоставляет числовую оценку уверенности, необходимую для отказа от сомнительных ответов.</Text>
                <Text>Магазин не включён в основной текстовый признак. Если использовать его как главный сигнал, модель будет хорошо воспроизводить наиболее частый тег магазина, но не сможет надёжно обрабатывать исключения. Поэтому в интерфейсе отдельно показывается контрольная метрика «Только магазин»: она характеризует упрощённый алгоритм, который для знакомого магазина всегда выбирает его наиболее частый тег.</Text>
            </GuideSection>
            <GuideSection title="Минимальные требования и их назначение">
                <Text>Текущая версия использует технические пороги, перечисленные ниже. Это защитные ограничения экспериментальной функции, а не универсальное правило о достаточности финансовых данных.</Text>
                <Bullet><strong>Не менее 50 ручных операций и двух разных тегов.</strong> При 50 операциях последние 20 образуют проверочную часть, а 30 более ранних остаются для первичного обучения. Меньший набор не позволяет одновременно выполнить оба минимальных требования.</Bullet>
                <Bullet><strong>Не менее пяти примеров тега в обучающей части.</strong> Тег с меньшим числом примеров не получает собственного порога уверенности. Пять примеров дают только право на проверку и не гарантируют активацию тега.</Bullet>
                <Bullet><strong>Не менее двух принятых предсказаний тега при проверке.</strong> Порог тега не подтверждается по одному удачному ответу.</Bullet>
                <Bullet><strong>Не менее пяти принятых предсказаний для всей модели и точность не ниже 90 %.</strong> Если условие не выполнено, автоматические назначения приостанавливаются.</Bullet>
                <Text>Для каждого тега проверяются пороги уверенности от 60 до 95 % с шагом 5 процентных пунктов. Выбирается минимальный порог, при котором принято не менее двух ответов и не менее 90 % из них правильны. Более низкий порог повышает покрытие, а более высокий обычно сокращает число ошибок.</Text>
            </GuideSection>
            <GuideSection title="Как проводится проверка">
                <Text>Операции сортируются по времени. Проверочная часть содержит последние 20 % набора, но не менее 20 операций; остальные, более ранние операции используются для первичного обучения. Случайное перемешивание не применяется, поскольку задача модели состоит в переносе прошлых закономерностей на новые покупки. После успешной проверки рабочая модель повторно обучается на всём доступном наборе ручных примеров.</Text>
                <Text><strong>Гипотетический пример.</strong> У пользователя есть 100 ручных операций. Первые 80 используются для первичного обучения, последние 20 — для проверки. Модель принимает 10 из 20 ответов, а остальные отклоняет как недостаточно уверенные. Если девять принятых ответов правильны, оценочная точность равна <Code>9 / 10 = 90 %</Code>, а покрытие — <Code>10 / 20 = 50 %</Code>. Пример описывает способ расчёта и не относится к данным конкретного пользователя.</Text>
            </GuideSection>
            <GuideSection title="Что означают показатели в профиле">
                <Bullet><strong>Оценочная точность</strong> — доля правильных тегов среди принятых предсказаний проверочной части. Она не учитывает операции, для которых модель отказалась выбирать тег, и не является гарантией будущего результата.</Bullet>
                <Bullet><strong>Покрытие</strong> — доля всех операций проверочной части, для которых модель приняла предсказание. Точность следует читать вместе с покрытием: высокая точность при низком покрытии означает, что модель отвечает редко.</Bullet>
                <Bullet><strong>Обучающих операций</strong> — число ручных операций, доступных текущему циклу обучения и проверки. В рабочей модели после успешной проверки используется весь этот набор.</Bullet>
                <Bullet><strong>Поддерживается тегов</strong> — число тегов, для которых найден и подтверждён порог уверенности. Статус «Мало данных» в списке означает, что порог не подтверждён. Причиной может быть менее пяти примеров в обучающей части, менее двух принятых ответов при проверке или точность ниже 90 %.</Bullet>
                <Bullet><strong>Только магазин</strong> — точность контрольного алгоритма по магазину на тех проверочных операциях, где магазин уже встречался в обучающей части. Эта метрика не показывает покрытие и не заменяет показатели основной модели.</Bullet>
                <Bullet><strong>Обновлено</strong> — дата и время завершения последнего обучения, метрики которого сейчас отображаются.</Bullet>
                <Alert severity="warning" sx={{ borderRadius: '8px' }}><strong>Гипотетический пример.</strong> Значение 100 % для отдельного тега означает только отсутствие ошибок среди принятых предсказаний этого тега. Если на проверке было восемь операций нужной категории, а модель приняла две и обе определила правильно, точность принятых ответов равна 100 %, но шесть операций остались без этого предсказания. Поэтому показатель нельзя интерпретировать как распознавание всех операций категории.</Alert>
            </GuideSection>
            <GuideSection title="Когда модель обновляется">
                <Text>Версия учебных данных изменяется после создания, редактирования или удаления ручной операции, импорта размеченных операций, переименования или удаления тега и изменения алиаса. В профиле появляется состояние «Есть новые данные». Обновление выполняется по кнопке «Обновить модель» или автоматически перед следующим предсказанием.</Text>
                <Bullet><strong>«Нужно больше примеров»</strong> — не выполнено минимальное требование к числу ручных операций или тегов.</Bullet>
                <Bullet><strong>«Готово к работе»</strong> — модель и поддерживаемые теги прошли проверку качества.</Bullet>
                <Bullet><strong>«Качество ниже порога»</strong> — данных достаточно для обучения, но итоговая точность или число принятых проверочных ответов не достигли установленного минимума.</Bullet>
                <Bullet><strong>«Есть новые данные»</strong> — сохранённые метрики относятся к предыдущей версии данных и должны быть пересчитаны.</Bullet>
                <Bullet><strong>«Не удалось обновить модель»</strong> — обучение завершилось технической ошибкой; новые операции сохраняются без автоматического тега.</Bullet>
            </GuideSection>
            <GuideSection title="Как влияют правила и алиасы">
                <Text><WikiLink to="regex">Правила и алиасы</WikiLink> приводят разные варианты названия товара или магазина к одному нормализованному значению. Модель получает одновременно исходное и нормализованное название. Исходное значение сохраняет различия между позициями, а нормализованное позволяет объединить историю эквивалентных написаний.</Text>
                <Text><strong>Гипотетический пример.</strong> В чеках встречаются названия «Молоко 3,2% 930 мл» и «МОЛОКО 3.2 930МЛ». Если они обозначают один товар, алиас может привести оба значения к названию «Молоко 3,2 %, 930 мл». После повторного обучения модель рассматривает их общую историю. Если товары различаются по составу или объёму и пользователь учитывает это в тегах, объединять их одним алиасом не следует.</Text>
                <Text>Изменение алиаса делает текущую модель устаревшей, поскольку меняет один из её признаков. Подробнее о категориях см. в разделе <WikiLink to="tags">«Теги и категории»</WikiLink>, а о переносе размеченной истории — в разделе <WikiLink to="data">«Импорт и экспорт»</WikiLink>.</Text>
            </GuideSection>
            <GuideSection title="Хранение и масштабирование">
                <Text>Постоянный бинарный файл модели не создаётся. В базе данных хранятся ручные операции, версия учебных данных, состояние обучения, дата обновления и рассчитанные метрики. Готовая модель размещается в оперативной памяти процесса сервера для выполнения быстрых предсказаний.</Text>
                <Text>В памяти одновременно хранится не более 32 недавно использованных персональных моделей. Если требуется модель, удалённая из кэша, сервер заново строит её из операций соответствующего пользователя. Это ограничение относится только к кэшу и не ограничивает число аккаунтов: данные и метрики каждого пользователя остаются независимыми.</Text>
            </GuideSection>
            <GuideSection title="Ограничения и действия пользователя">
                <Bullet>Исправляйте ошибочный тег вручную. После обновления модели исправленная операция станет подтверждённым примером.</Bullet>
                <Bullet>Используйте один и тот же тег для операций, которые должны рассматриваться как одна категория. Противоречивые ручные примеры снижают уверенность.</Bullet>
                <Bullet>Не объединяйте алиасом разные товары или магазины только ради сокращения списка названий.</Bullet>
                <Bullet>После появления нового тега или изменения привычек оценивайте одновременно общую точность, покрытие и статус конкретного тега.</Bullet>
                <Text>Модель не анализирует состав товара, текст комментария, изображения чека или сведения из внешних источников. Она не отправляет историю операций внешнему сервису машинного обучения. Общая структура хранения описана в разделе <WikiLink to="storage">«Как хранятся данные»</WikiLink>, условия обработки персональных данных — в <Link component={RouterLink} to="/privacy" color="primary" underline="hover" fontWeight={700}>политике конфиденциальности</Link>.</Text>
            </GuideSection>
        </>
    )
}

const PAGE_CONTENT: Record<GuideSlug, ReactNode> = {
    'quick-start': <QuickStartGuide />,
    receipts: <ReceiptsGuide />,
    storage: <StorageGuide />,
    math: <MathGuide />,
    regex: <RegexGuide />,
    tags: <TagsGuide />,
    'auto-tagging': <AutoTaggingGuide />,
    data: <DataGuide />,
    pages: <PagesGuide />,
    interpretation: <InterpretationGuide />,
    commercial: <CommercialGuide />,
}

export function AboutPage() {
    const theme = useTheme()
    const { topic = 'quick-start' } = useParams<{ topic?: string }>()
    const current = GUIDE_PAGES.find((page) => page.slug === topic)

    useEffect(() => {
        document.querySelector('main')?.scrollTo({ top: 0, behavior: 'smooth' })
    }, [topic])

    if (!current) return <Navigate to="/about/quick-start" replace />

    return (
        <Stack spacing={2.5} sx={{ maxWidth: 1080, mx: 'auto', width: '100%', pb: 2 }}>
            <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', md: 'minmax(0, 1fr) 260px' }, gap: { xs: 1.5, md: 2.5 }, alignItems: 'start' }}>
                <Card component="article" sx={{ order: { xs: 1, md: 1 }, p: { xs: 2, sm: 3.5 } }}>
                    <Stack spacing={{ xs: 2.25, sm: 3 }}>
                        <Box>
                            <Typography variant="h4" sx={{ fontSize: { xs: 24, sm: 30 }, mb: 0.75 }}>{current.title}</Typography>
                            <Typography color="text.secondary">{current.description}</Typography>
                        </Box>
                        <Divider />
                        {PAGE_CONTENT[current.slug]}
                        <Divider />
                        <Box sx={{ display: 'flex', justifyContent: 'space-between', gap: 1, flexWrap: 'wrap' }}>
                            {(() => {
                                const currentIndex = GUIDE_PAGES.findIndex((page) => page.slug === current.slug)
                                const previous = GUIDE_PAGES[currentIndex - 1]
                                const next = GUIDE_PAGES[currentIndex + 1]
                                return <>
                                    {previous ? (
                                        <Link component={RouterLink} to={`/about/${previous.slug}`} color="primary" underline="hover" sx={{ display: 'inline-flex', alignItems: 'center', gap: 0.5, fontWeight: 700 }}>
                                            <ArrowBackOutlinedIcon sx={{ fontSize: 18 }} /> Назад: {previous.title}
                                        </Link>
                                    ) : <Box />}
                                    {next ? (
                                        <Link component={RouterLink} to={`/about/${next.slug}`} color="primary" underline="hover" sx={{ display: 'inline-flex', alignItems: 'center', gap: 0.5, fontWeight: 700 }}>
                                            Далее: {next.title} <ArrowForwardOutlinedIcon sx={{ fontSize: 18 }} />
                                        </Link>
                                    ) : null}
                                </>
                            })()}
                        </Box>
                    </Stack>
                </Card>

                <Card component="nav" aria-label="Разделы справки" sx={{ order: { xs: 2, md: 2 }, p: 1, position: { md: 'sticky' }, top: { md: 0 } }}>
                    <Stack spacing={0.5} sx={{ display: { xs: 'grid', md: 'flex' }, gridTemplateColumns: { xs: 'repeat(2, minmax(0, 1fr))' }, gap: { xs: 0.5, md: 0 } }}>
                        {GUIDE_PAGES.map(({ slug, title, description, icon: Icon }) => {
                            const active = current.slug === slug
                            return (
                                <Box
                                    key={slug}
                                    component={RouterLink}
                                    to={`/about/${slug}`}
                                    aria-current={active ? 'page' : undefined}
                                    sx={{ display: 'flex', gap: 1.25, alignItems: 'center', minWidth: 0, p: { xs: 1, md: 1.25 }, borderRadius: '7px', textDecoration: 'none', color: active ? softFg(theme) : 'text.primary', bgcolor: active ? softBg(theme) : 'transparent', '&:hover': { bgcolor: active ? softBg(theme) : 'action.hover' } }}
                                >
                                    <Icon sx={{ fontSize: 20, flexShrink: 0 }} />
                                    <Box sx={{ minWidth: 0 }}>
                                        <Typography sx={{ fontSize: 13.5, fontWeight: 700 }}>{title}</Typography>
                                        <Typography color="text.secondary" sx={{ display: { xs: 'none', md: 'block' }, fontSize: 11.5, lineHeight: 1.35 }}>{description}</Typography>
                                    </Box>
                                </Box>
                            )
                        })}
                        <Divider sx={{ gridColumn: { xs: '1 / -1', md: 'auto' }, my: 0.5 }} />
                        <Box component={RouterLink} to="/privacy" sx={{ display: 'flex', gap: 1.25, alignItems: 'center', minWidth: 0, p: { xs: 1, md: 1.25 }, borderRadius: '7px', textDecoration: 'none', color: 'text.primary', '&:hover': { bgcolor: 'action.hover' } }}>
                            <SecurityOutlinedIcon sx={{ fontSize: 20 }} />
                            <Typography sx={{ fontSize: 13.5, fontWeight: 700 }}>Конфиденциальность</Typography>
                        </Box>
                    </Stack>
                </Card>
            </Box>
        </Stack>
    )
}
